"use strict";function query(n){$.ajax({url:_global.root+"applicants/index",dataType:"html",method:"POST",data:{FullName:$("#FullName").val(),PositionId:$("#PositionId").val(),Status:$("#Status").val(),FromDate:$("#FromDate").val(),ToDate:$("#ToDate").val()},beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#applicants-detail").html(n);floatThead("table#data")},error:function(){alert(_messages.errorTryAgain)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteApplicant(n,t){confirm("Are you sure you want to delete this applicant?",function(){$.post(_global.root+"applicants/Delete",{id:n,fileName:t},function(t){t.IsSuccessful?($("#row"+n).remove(),autoIndex()):alert(t.Message)})})}function eventExportExcel(){$("#exportExcel").on("click",function(n){n.preventDefault();window.location.href=_global.root+"Export/ApplicantsReport?fullName="+$("#FullName").val()+"&positionId="+$("#PositionId").val()+"&status="+$("#Status").val()+"&fromDate="+$("#FromDate").val()+"&toDate="+$("#ToDate").val()})}$(document).ready(function(){$("#FullName").keyup(function(n){n.keyCode===13&&query(!1)});$("#submit").on("click",function(){query(!1)});query(!0);eventExportExcel()});